export const compactMeta={slug:'models/compact-recipes',title:'Small and On-Device Model Recipes',description:'Connect small-model capacity, repeated depth, training investment and hardware-aware deployment without confusing their budgets.',date:'2026-04-20',updated:'2026-10-18',topicPath:['models'],tags:['small models','on-device','embedding tax','Nanbeige','Gemma 4','Apple AFM','Liquid','looped transformer','RLHF','agent training'],learningGoals:['Separate stored weights, active parameters, depth and cache.','Read small-model reports as complete training and deployment recipes.','Check behavioral and agent results under their actual budgets.'],related:['models/recurrence','models/attention','models/moe','training/numerics','training/data','training/scaling','execution/speculation'],prototype:false,visibility:'public',kind:'dense-topic'};
export const compactAliases=['ai/architectures/model-reports/gemma-4-technical-report','ai/architectures/model-reports/third-generation-apple-foundation-models','ai/architectures/model-families/frontier-small-language-models','ai/architectures/model-reports/nanbeige4-3b-technical-report','ai/architectures/model-reports/nanbeige4-2-3b-unlocking-agentic-capabilities'];
export const compactSections=[['objective','Which resource must be small?'],['embedding','Account for the vocabulary'],['liquid','Liquid: hardware and repeated exposure'],['nan4','Nanbeige 4: invest in the training stream'],['schedule','Align the data curriculum with FG-WSD'],['supervision','Find a good answer, then reconstruct its trace'],['distillation','Correct student failures at two levels'],['nan4-rl','Refresh reasoning difficulty on-policy'],['nan42','Nanbeige 4.2: reuse depth, not cache state'],['loop','Trace one token through two passes'],['environments','Build tasks with executable consequences'],['curriculum','Preserve recovery without imitating bad turns'],['behavior','Regularize termination before rewarding efficiency'],['length','Make the length penalty depend on competence'],['agent-rl','Agent actions need denser feedback'],['gemma','Gemma: one family, different model designs'],['gemma-cache','Compose local attention and cache reductions'],['modalities','Put modality work in encoders or the decoder'],['deployment','Train the arithmetic and interface you will serve'],['gemma-training','Training infrastructure is part of the recipe'],['apple','Apple: choose a flash-backed subnetwork'],['apple-training','Specialize a common foundation for each tier'],['apple-api','Route the application, not just its tokens'],['apple-evidence','Read Apple’s product comparisons in scope'],['evidence','Compare scores with their complete budgets'],['transfer','Turn a recipe into a controlled experiment'],['sources','Sources and connected recipes']];
const refs={liquid:'https://www.liquid.ai/blog/lfm2-5-350m-no-size-left-behind',nan4:'https://arxiv.org/abs/2512.06266',nan42:'https://arxiv.org/abs/2607.22083',config:'https://huggingface.co/Nanbeige/Nanbeige4.2-3B/blob/main/config.json',gemma:'https://arxiv.org/abs/2607.02770',apple:'https://machinelearning.apple.com/research/introducing-third-generation-of-apple-foundation-models'};
const table=(caption,heads,rows)=>baseTable(caption,heads,rows).replace('<div class="dense-table-wrap">','<div class="dense-table-wrap" tabindex="0" role="region" aria-label="Scrollable small-model comparison">');
const scene=(id,title,controls,body,play=false)=>`<div class="topic-scene" data-compact-lab="${id}"><h3>${title}</h3>${controls}${play?'<div class="dense-actions"><button type="button" data-play>Play</button><button type="button" data-reset>Replay</button></div>':''}<div data-body>${body}</div></div>`;
function embeddingBody(v,tied){const b=embeddingBudget(v,3072,tied);return `<p>V=${v.toLocaleString('en-US')}, d=3,072; fixed non-embedding body=3B. Input matrix: ${(b.input/1e6).toFixed(3)}M parameters. Additional output matrix: ${(b.output/1e6).toFixed(3)}M.</p><div class="compact-budget" role="img" aria-label="Embedding and output matrices ${(100*b.fraction).toFixed(2)} percent of total"><span style="flex:${b.fraction}">Vocabulary</span><span style="flex:${1-b.fraction}">Body</span></div><p>Total ${(b.total/1e9).toFixed(6)}B; vocabulary matrices ${(100*b.fraction).toFixed(2)}%. This isolates V×d storage, not inference latency. Per-layer embeddings, biases, modality encoders and drafters are excluded. Tied output uses the input matrix again; the output operation still costs computation.</p>`;}
function loopBody(n,shared,step){const a=loopInventory(n,2,shared,step);return `<div class="compact-passes">${[1,2].map(r=>`<div><b>Pass ${r} · same 22 weights</b><div class="compact-blocks">${Array.from({length:22},(_,i)=>`<span class="${step>(r-1)*22+i?'compact-done':''}" title="Pass ${r}, block ${i+1}">${i+1}</span>`).join('')}</div></div>`).join('')}</div><p>${a.complete?'Readout can predict the next token.':`Next application: pass ${a.round}, physical block ${a.block}.`} Completed ${step}/44 applications; stored depth stays 22.</p><p>${n.toLocaleString('en-US')} cached tokens; 8 KV heads × 128 dimensions; K and V; two-byte elements; ${a.copies} cache copy/copies per physical layer. Analytical cache ${(a.cache/2**30).toFixed(3)} GiB per sequence. The released two-pass recipe keeps separate caches. The shared choice is a reported lower-quality ablation, not an interchangeable implementation.</p><p>Batch=1. This assumes conventional full K/V storage and excludes padding, allocation, metadata, temporary buffers and quantization. Playback explains layer applications, not measured latency.</p>`;}
function lengthBody(l,p,on){const a=competencePenalty(l,1000,4000,p,1,on);return `<p>Synthetic problem: median correct historical length b=1,000; maximum L=4,000; α=1. Current correct fraction p=${p.toFixed(1)}; response length ${l}.</p><div class="compact-penalty" role="img" aria-label="Length penalty ${a.penalty.toFixed(3)} of maximum one"><span style="width:${100*a.penalty}%"></span></div><p>Clipped excess ${a.excess.toFixed(3)}; subtract ${a.penalty.toFixed(3)} from the base reward. ${on?(l<=1000?'Within the historical budget: no length penalty.':p===0?'No current correct responses: this competence-scaled penalty is zero.':'Excess length is penalized in proportion to current competence.'):'Free-expansion phase: no length penalty.'}</p><p>This is exact arithmetic for the stated rule, not a learned accuracy curve. A problem with no correct history needs an explicit fallback; b must be below the maximum to avoid a zero denominator.</p>`;}
export function compactReader(link){return topic(compactMeta,compactSections,'A small parameter label does not specify the training investment, execution depth or deployment footprint.',`
<p>Small-model design starts with a deployment constraint. A phone may run out of working memory. A coding agent may instead spend most time in tools. A high-volume extraction service may care about total tokens per second. These constraints do not select the same architecture.</p><p>The recipes below attack different parts of that budget. Nanbeige spends heavily on data and post-training. Gemma composes attention, modality and numerical choices. Liquid targets hardware-friendly operators. Apple changes when expert weights move from storage into working memory.</p>
${section('objective','Which resource must be small?',`<p>Separate four quantities: stored parameters, parameters used in a token's pass, layer applications per token, and state retained across tokens. A sparse model can have low active compute yet require all experts in memory. A looped model stores one stack but executes it repeatedly.</p><p>Also separate one-time training from repeated inference. Overtraining can be rational when a small deployed model serves enough requests. It does not make the original training inexpensive. Compare total lifecycle cost under the target workload, not just parameter count.</p>${table('Different small-model objectives',['Recipe','Primary intervention','Cost that remains'],[['Liquid','Hardware-friendly hybrid operators and overtraining','Attention/cache and task-dependent quality'],['Nanbeige 4','Data curriculum, distillation, staged RL','23T training exposure and long outputs'],['Nanbeige 4.2','Two-pass shared depth and agent curriculum','44 layer applications; separate loop caches'],['Gemma 4','Local/global attention, cache structure, QAT, drafting','Total embeddings/experts, encoders and runtime state'],['Apple AFM 3','Request-conditioned flash-backed experts','Flash transfer, shared weights, cache and reselection']])}`)}
${section('embedding','Account for the vocabulary',`<p>An input embedding has V rows and d columns. An untied output head adds another V×d matrix. When the transformer body is small, these matrices can consume a large fraction of the parameter budget.</p>${eq(String.raw`P=P_{\rm body}+Vd+\mathbf1_{\rm untied}Vd`, 'V>0 is vocabulary size; d>0 is embedding width; the indicator is 1 for an untied output matrix and 0 for a shared one. Count shared storage once. This counts these matrices, not every tensor in a checkpoint.')}<p>Embeddings are not inactive or useless for reasoning. They represent input tokens and support output discrimination. The budget question is whether this vocabulary and width use scarce storage effectively. Changing the tokenizer also changes token counts, sequence lengths, multilingual coverage and teacher/student alignment.</p>${scene('embedding','Hold the body fixed; change the vocabulary contract','<label>Vocabulary<select aria-label="Embedding vocabulary"><option value="32000">32,000</option><option value="64000">64,000</option><option value="166144" selected>166,144</option><option value="262144">262,144</option></select></label><label>Output matrix<select aria-label="Embedding tying"><option value="untied">Untied</option><option value="tied">Tied</option></select></label>',embeddingBody(166144,false))}<p>With 166,144 entries and width 3,072, two matrices contribute 1.020789B parameters. Adding a hypothetical exact 3B body gives 4.020789B. This explains the rounded Nanbeige label; it is not a tensor-by-tensor checkpoint count. Its current configuration declares untied embeddings. ${cite(refs.config,'Nanbeige configuration')}</p>`)}
${section('liquid','Liquid: hardware and repeated exposure',`<p>The earlier interview covers models from 350M to 24B parameters, with cars and phones as deployment examples. It prioritizes memory limits, focused tasks such as tool use and summarization, and latency. A stored parameter budget and factual knowledge capacity are related but not interchangeable.</p><p>Liquid's LFM2 architecture combines gated short convolutions and attention. Short convolutions keep a bounded local history and suit some edge kernels; attention retains selective access to earlier tokens. Faster kernels on a stated device do not establish universal superiority over GQA or sliding attention.</p><p>LFM2.5-350M extends the 350M model's pretraining from 10T to 28T tokens and adds large-scale RL. Its release targets extraction, structured output and tool use. This is a version-specific budget, not the exposure of every LFM2 model. ${cite(refs.liquid,'Liquid release')}</p><p>A frequently cited compute-optimal reference uses about twenty training tokens per parameter: around 7B tokens for 350M parameters. The 28T release exposure is 4,000 times that token budget. This compares exposures, not training FLOPs or a universal optimum. A small deployment can justify heavy one-time training, but training is not automatically cheap. <a href="${link('training/scaling')}">Scaling Laws →</a></p><p>The earlier interview note describes a failure-control recipe: sample five diverse responses and one deterministic response, judge them, and use a looping response as a rejected preference example. “Doom looping” means continued repetitive generation until termination or the execution budget; a finite run does not literally produce infinitely many tokens. <a href="${link('post-training/preferences')}">Preference Optimization →</a> explains how DPO learns from the preferred and rejected responses. The interview also describes verifiable rewards and n-gram repetition penalties. Those interview details have no linked primary protocol in the original; treat them as reported guidance, not a reproduced release recipe.</p><p>A looping candidate is not automatically a valid preference pair. The positive must satisfy the task, and the rejection must reflect the desired behavior. A model that repeats until its budget ends can fail an executable verifier, but neither DPO nor a repetition penalty guarantees termination.</p><p>Tools can supplement limited internal knowledge. They introduce their own retrieval, latency and reliability limits. Recursive processing can avoid placing an entire document in context, but lost evidence and failed tool calls remain possible. Using a teacher vocabulary can simplify distillation alignment while increasing vocabulary storage. The original 63% embedding and 90% effective-parameter claims lack checkpoint-specific counts; use the budget equation rather than generalizing either.</p><p>The interview emphasizes knowledge and tool-use evaluations. The release names GPQA Diamond and τ²-Bench, rather than the earlier shorthand “T2Bench.” Liquid recommends this checkpoint for extraction and tool workflows, not math, code or creative writing. External search can extend available evidence but cannot guarantee more reliable knowledge than a larger model. Validate returned evidence and recursive summaries before using them.</p>`)}
${section('nan4','Nanbeige 4: invest in the training stream',`<p>The original Nanbeige4-3B is a conventional dense Llama-style model, not a looped transformer. Its main intervention is a training pipeline: 23T tokens, large reasoning SFT, answer refinement, dual-level distillation and staged RL. The later 4.2 comparison identifies roughly 4B total and 3B non-embedding parameters for both releases.</p><p>The original ${inlineMath(String.raw`\frac{23\times10^{12}}{3\times10^9}\approx7{,}667`)} density uses the named 3B denominator. With rounded 4B total, the ratio is 5,750. Neither is training FLOPs or unique corpus size. Always state the denominator when comparing these figures.</p><p>The corpus includes web, scholarship, books, code and synthetic QA, textbooks, lectures and long reasoning. Synthetic material supplies 15% of final token exposure. Quality tagging starts with more than sixty dimensions and retains twenty. A strong annotator supplies labels that a smaller model learns to apply at scale.</p><p>Content-related labels outperform formatting labels in this recipe; scores 0–9 outperform binary judgments. Lexical/vector retrieval against trusted seeds complements intrinsic quality scoring. Provenance and learned quality scores constrain which retrieved samples are trusted. The pipeline retains a 12.5T pool and a 6.5T higher-quality subset, then deliberately repeats that higher-quality subset for at least two epochs to reach 23T exposure. Repetition changes training weight; it does not create new independent documents. ${cite(refs.nan4,'Nanbeige 4 report')}</p>`)}
${section('schedule','Align the data curriculum with FG-WSD',`<p>Warmup–stable–decay changes the learning rate. Fine-Grained WSD also changes the data mixture inside the stable phase. Earlier broad exposure supports coverage; later higher-quality mass emphasizes the chosen capabilities. A constant LR during that transition avoids changing two variables at once.</p>${table('Nanbeige 4 stages; T token exposure',['Stage','Tokens','Learning rate'],wsdStages.map(r=>[r[0],r[1],r[2]]))}<p>The stages sum to 23T. During decay, Adjusting Base Frequency extends context to 64K. This is a trained extension, not proof of equally strong retrieval at every position.</p>${table('Controlled 1B-model, 1T-token schedule comparison',['Schedule','GSM8K','CMath','BBH','MMLU','CMMLU','MMLU-Pro'],[['WSD',27.1,34.5,29.3,49.2,50.3,16.87],['FG-WSD',34.3,39.5,31.6,50.6,51.9,18.64]])}<p>The experiment uses 1T stable-phase exposure plus a fixed 100B-token decay corpus. WSD shuffles a 1:1 high/medium-quality mixture; FG-WSD uses 750B mixed tokens then 250B high-quality tokens. GSM8K, CMath and BBH use 3-shot evaluation; the other three tasks use 5-shot. The largest gains occur on the targeted math/reasoning tasks. The authors connect these gains to reasoning density in selected data. This supports the combined schedule/curriculum, not a universal best data ordering.</p><p>Base evaluation also uses a common downstream treatment: three public SFT datasets, 500K examples each, two epochs and matched hyperparameters across three bases. The bases are Nanbeige4-3B-Base, Qwen3-4B-Base and Qwen3-8B-Base. Nanbeige generally yields the strongest reasoning checkpoint. Nine runs reduce reliance on one favorable dataset. The comparison still emphasizes reasoning, where this pretraining mixture was optimized.</p>`)}
${section('supervision','Find a good answer, then reconstruct its trace',`<p>Cold-start reasoning SFT uses about 30M cleaned examples at 32K: roughly 50% mathematics, 30% science and 20% code. Scaling from about 0.5M to 35M examples keeps improving the reported AIME/GPQA results. This does not prove that all small-model tasks benefit equally from that scale.</p><p>The overall 64K SFT mix broadens to 40% math/subject reasoning, 30% general QA/writing, 20% agents and 10% code. The construction pipeline separates answer search from the trace used to supervise the student.</p><ol><li>Create a task-specific checklist and generate candidates with teacher models and the current model.</li><li>Evaluate correctness, completeness, executability, consistency and safety.</li><li>Critique and revise the answer, then repeat checks.</li><li>Condition chain completion on the instruction and refined answer; create a short summary and a coherent reasoning trace.</li></ol><p>The final target joins reconstructed reasoning and the refined answer. An offline revision loop is not recurrent transformer depth. A plausible reconstructed trace also does not prove that it records the teacher's actual internal reasoning.</p>`)}
${section('distillation','Correct student failures at two levels',`<p>Dual-Level Preference Distillation uses positive responses from Nanbeige3.5-Pro and negatives from the student. Retain pairs with a clear quality difference. Student-generated negatives focus supervision on states the deployed policy actually visits.</p><p>A DPO-style sequence margin says which answer should win. Teacher-distribution supervision supplies local alternatives on both positive and negative prefixes. Distilling on a wrong trajectory is not instructing the student to repeat its sampled wrong token: the target is the teacher's distribution at that prefix.</p>${eq(String.raw`\mathcal L=\mathcal L_{\rm sequence}+\lambda_+\mathcal L_{\rm teacher}(y^+)+\lambda_-\mathcal L_{\rm teacher}(y^-)`, 'Conceptual decomposition: y⁺ is the preferred teacher response, y⁻ an inferior student response; λ₊,λ₋≥0 weight teacher targets at their respective prefixes. Targets on y⁻ do not label its sampled wrong action correct. Exact coefficients and reduction need the training specification.')}${eq(String.raw`\mathcal L_{\rm KD}=\sum_t D_{\rm KL}\!\left(\pi_T(\cdot\mid x,y_{<t})\,\Vert\,\pi_\theta(\cdot\mid x,y_{<t})\right)`, 'Generic forward-KL teacher supervision, not a disclosed exact DPD implementation. x is the instruction; the prefix contains response tokens before position t; T is the teacher and θ the student. Sum over supervised positions. Vocabulary distributions must be normalized; student support must cover teacher mass. A mean needs its own denominator.')}<p>Teacher probabilities describe alternatives at each prefix, not just one preferred next token. <a href="${link('post-training/distillation')}">Distillation →</a> explains the KL direction. <a href="${link('post-training/preferences')}">Preference Optimization →</a> explains the sequence margin.</p><p>The report gives approximate improvements over SFT of 8% AIME, 10% GPQA, 30% BFCL V4 and 8% preference evaluation. The report calls these relative gains, not percentage-point differences. RL from the distilled checkpoint also improves more than RL started directly from SFT. Component-level evidence is less detailed than the FG-WSD ablation; do not attribute the whole gain to negative-prefix supervision alone.</p>`)}
${section('nan4-rl','Refresh reasoning difficulty on-policy',`<p>Nanbeige 4 separates STEM, practical code and human-preference stages because capabilities progress at different rates. Its reported on-policy GRPO removes the KL penalty and masks truncated sequences. That is a recipe choice, not a general prescription to remove KL everywhere.</p><p>Before each stage, sample sixteen responses per question and retain measured pass rates strictly between 10% and 90%. For binary outcomes, this keeps two through fourteen successes out of sixteen. Resample after the policy changes; “difficulty” belongs to a policy and sampling setup, not permanently to the prompt.</p><p>A Python-backed STEM verifier checks numerical/symbolic equivalence. Coding construction can proceed backward from a valid solution to executable public/private tests and then a problem statement. Verifier and prompt must express the same contract; executable tests can still be incomplete or exploitable.</p><p>Final Thinking evaluation uses temperature 0.6, top-p 0.95 and maximum output 64K. AIME averages eight runs; most others three. Strong math/function-calling results coexist with weaker full-stack and broader knowledge results. The selected evaluation table below preserves that uneven profile. The Thinking checkpoint is Nanbeige4-3B-Thinking-2511. Broader knowledge, full-stack coding and multi-turn instruction following remain weaker dimensions.</p>`)}
${section('nan42','Nanbeige 4.2: reuse depth, not cache state',`<p>Nanbeige 4.2 shifts toward repository coding, tool workflows, office artifacts and recovery. It trains a two-pass stack from scratch on 28T tokens. The reported recipe increases math, code, synthetic QA and a small agent-trajectory component; complete mixture weights and compute remain undisclosed.</p><p>The checkpoint has 22 physical layers, width 3,072, FFN width 10,752, 48 query heads, 8 KV heads and head width 128. Two passes create 44 layer applications with one stored stack. Maximum configured context is 262,144; this is not an assurance that every task works at that length.</p><p>From-scratch looping beats upcycling in the report's experiments. Upcycling starts with an ordinary pretrained model, adds the loop, then continues training. Learning compatible representations from initialization is the authors’ explanation, not an isolated causal result. The authors report about 75% of standard-transformer token efficiency for two passes. They disclose neither a full loop-depth table nor enough conditions to use that figure as a serving-speed prediction.</p><p>Separate pass caches give greater quality gains than sharing them. The chosen full loop therefore retains both cache states. Sharing halves this cache component but changes the computation. Architecture and data both change relative to Nanbeige 4, so base improvements do not isolate looping. The 28T/3B ratio is approximately 9,333 training tokens per non-embedding parameter, not a FLOP count. ${cite(refs.nan42,'Nanbeige 4.2 report')}</p>${table('Nanbeige base models; reported scores, not an isolated looping ablation',['Model','GSM8K','BBH','MBPP','MMLU-Pro','SuperGPQA','GPQA'],[['Nanbeige4-3B',85.9,70.7,60.7,47.6,24.8,36.2],['Nanbeige4.2-3B',92.7,81.6,67.6,63.8,35.2,53.3]])}<p>For the verified query, KV and output projection shapes, see <a href="${link('models/recurrence#nanbeige')}">Nanbeige’s attention-width comparison →</a>. The attention inner width need not equal the residual width.</p>`)}
${section('loop','Trace one token through two passes',`${scene('loop','One weight stack; two hidden-state roles','<label>Cached tokens<select aria-label="Loop context"><option value="32768">32,768</option><option value="65536">65,536</option><option value="262144">262,144</option></select></label><label>Pass cache<select aria-label="Loop cache policy"><option value="separate">Separate — released recipe</option><option value="shared">Shared — ablation</option></select></label><label>Completed applications<input aria-label="Loop applications" type="range" min="0" max="44" step="1" value="0"></label>',loopBody(32768,false,0),true)}${eq(String.raw`M_{\rm KV}=2LRNH_{\rm KV}d_hb`, 'Bytes for full separate pass-indexed K/V caches: L physical layers, R passes, N cached tokens, Hkv heads, dh entries per head, b bytes per entry. Counts are positive integers; b>0. No cache sharing, window eviction, padding or allocator overhead is included.')}<p>For 22 layers, two passes and BF16-like two-byte storage, 32K requires 5.5 GiB analytically. At 256K, it requires 44 GiB. Quantization, offload or a different backend can change storage, but parameter reuse alone does not make maximum context practical on a phone.</p><p>Each token passes through both depths before readout. Later tokens need the corresponding earlier states for each effective depth. Collapsing pass-indexed caches changes those inputs; it is not simply an allocator optimization. <a href="${link('models/recurrence')}">Recurrent and Looped Models →</a></p>`)}
${section('environments','Build tasks with executable consequences',`<p>Repository tasks begin at a reference patch's parent commit. Reconstruct dependencies and tests in a container. Hide the reference patch and grading tests from the agent. Fail-to-pass tests confirm the missing behavior; pass-to-pass tests protect existing functionality. Neither alone guarantees that all relevant behavior is correct.</p><p>Mine current model failures for new repository/patch search cues. Generate trajectories through Claude Code, OpenHands, SWE-agent and specialized Codex drivers. Their prompts, editing interfaces and context policies differ. Diversity reduces one-interface overfitting only if those differences remain compatible with the intended tool contract.</p><p>Complex tool-use synthesis starts from thousands of Model Context Protocol (MCP) specifications. Tools are bundled for composable search, data access, repository operations, execution and testing. It combines executable local Python tools backed by real data, live services for changing information, and model-simulated tools for expensive runtimes. Simulated realism needs independent checks; a correct simulated task can still fail on a real service.</p><p>Generate an instruction together with a Python verifier. Repeated solver attempts guide difficulty evolution along tool-chain depth, retrieval, parameter inference and cross-tool composition. Office synthesis clusters documents, slides, spreadsheets, code and other structured files into coherent bundles. A sandboxed synthesis agent creates tasks, rubrics, trajectories and deliverables. An independent judge checks those outputs before they return to the artifact pool. Recycling validated deliverables expands the pool but can amplify synthetic biases.</p><p>Repository trajectories must pass target/regression tests. Turn-level filtering rejects invalid calls, non-terminating loops, redundant actions and context truncation. Keep a disjoint fast validation suite; do not let iterative task generation leak its reference outputs into training.</p>`)}
${section('curriculum','Preserve recovery without imitating bad turns',`${table('Nanbeige 4.2 SFT; supervised target-token shares, not example shares',['Stage','Context','Reasoning','General','Agentic'],agentCurriculum.map((r,i)=>[i+1,r.context,r.reasoning+'%',r.general+'%',r.agent+'%']))}<p>The curriculum grows context and agent share together. It first establishes reasoning, then shifts toward long tool interactions. Because both change, the final result does not isolate the effect of context extension.</p><p>A successful trajectory may contain a failed action followed by useful recovery. Deleting the failure and observation creates an unreal history. Imitating the failed action teaches the wrong behavior. Keep its context but exclude its assistant target from loss.</p>${eq(String.raw`\mathcal L_{\rm SFT}=\sum_t m_t\ell_t,\qquad m_t\in\{0,1\}`, 'mₜ selects reliable assistant targets; ℓₜ is their declared supervised loss. Turn labels must map to token targets. Attention/context can retain a failed turn. A mean requires an explicit nonempty target denominator.')}<p>Specify token masks and reduction denominators as well as turn labels. A masked target can still influence later loss through its representation unless it is explicitly detached. “No imitation loss on this turn” does not mean “no gradient anywhere through its history.”</p>`)}
${section('behavior','Regularize termination before rewarding efficiency',`<p>After SFT, Nanbeige 4.2 still repeats, reflects cyclically, duplicates answers and fails to terminate. A point-wise reward model evaluates correctness, relevance, format, termination, safety and user experience. Think-focused RLHF comes first; predominantly Non-Think RLHF follows.</p>${table('LiveCodeBench-V6; every checkpoint evaluated in Think mode',['Checkpoint','Accuracy','Bad-case rate','Mean output tokens'],behaviorResults)}<p>Non-Think training transfers behavioral gains back to Think evaluation. This is not a comparison that switches inference mode to obtain shorter outputs. Accuracy rises from 65.45 to 72.10 while mean output drops from 25,905 to 15,182. The reported bad-case metric reaches zero in this sample, not proof that future failures are impossible.</p><p>Behavioral control can expose existing capability by allowing a correct response to finish. It does not establish that reward training added no knowledge or that the improvement comes from one reward component.</p>`)}
${section('length','Make the length penalty depend on competence',`<p>A uniform token penalty may stop hard-problem exploration too early. Nanbeige instead keeps a problem-specific median of correct historical lengths. Penalize only length above that budget, scale the penalty by current success fraction, and alternate constrained phases with free expansion.</p>${eq(String.raw`r_i=r_i^{\rm base}-\alpha p_q\operatorname{clip}\!\left(\frac{L_i-b_q}{L_{\max}-b_q},0,1\right)`, 'bq is the median of a nonempty historical correct-response set, computed once before this reasoning-RL stage and fixed throughout it. pq∈[0,1] is current correctness fraction; α≥0 is the coefficient. Require Lmax>bq. Count lengths consistently. Free-expansion phases disable this penalty; the formula is not an execution stop.')} ${scene('length','Separate excess length from current competence','<label>Response length<input aria-label="Response length" type="range" min="0" max="5000" step="100" value="2500"></label><label>Correct fraction<input aria-label="Correct fraction" type="range" min="0" max="10" step="1" value="5"></label><label>Phase<select aria-label="Length control phase"><option value="constrained">Constrained</option><option value="free">Free expansion</option></select></label>',lengthBody(2500,.5,true))}<p>At p=0.5 and length 2,500, clipped excess is 0.5 and the penalty is 0.25. Length at or below 1,000 gets no penalty. Length beyond 4,000 reaches the same bounded maximum; this reward expression alone is not an execution stop rule.</p><p>The reported budget does not track later improvements: successful histories from earlier checkpoints set it once. Updating that median online would be a different adaptation. Audit missing-history fallback, phase lengths and reward scale before transferring the method.</p>`)}
${section('agent-rl','Agent actions need denser feedback',`<p>Terminal success gives weak credit assignment over long tool sequences. Nanbeige combines outcomes with action-centric rubrics for valid calls, information gain, progress and recurring mistakes. Process rewards supplement, not replace, final verification.</p><p>For compact agent RL, the recipe favors shorter trajectories and relatively high pass@8. This differs from reasoning's mixed-outcome difficulty filter. Long-horizon action tasks can provide too little useful feedback to a small initial policy. Pass@8 measures at least one success across attempts; it is not the same statistic as the correct-response fraction.</p><p>The report shows about a 20% drop in normalized single-turn errors and validation rising from 66.0 to a peak 71.0. The peak is not necessarily the final checkpoint. Full RL improves accuracy and output length across six reported tasks, but reward coefficients, datasets and complete serving cost remain undisclosed.</p>`)}
${section('gemma','Gemma: one family, different model designs',`${table('Gemma 4 family; parameter conventions are not interchangeable',['Model','Parameters','Vision','Audio'],[['E2B','2.3B effective; about 5B total','150M frozen ViT','305M frozen encoder'],['E4B','4.5B effective; about 8B total','150M frozen ViT','305M frozen encoder'],['12B','Dense 12B','Raw-patch projection','Raw-chunk projection'],['26B-A4B','26B total; about 3.8B active','550M frozen ViT','Not reported'],['31B','Dense 31B','550M frozen ViT','Not reported']])}<p>Per-layer embeddings explain part of the edge models' stored/effective gap. This is not MoE routing. The shared decoder design uses pre/post RMSNorm, QK normalization and about 262K SentencePiece entries. Encoders and drafters add parameters beyond a simple backbone label.</p><p>The 12B encoder-free experiment and 26B MoE are distinct designs, not just larger E2B models. Compare which computation each family member changes before extrapolating a small-model finding. ${cite(refs.gemma,'Gemma report')}</p>`)}
${section('gemma-cache','Compose local attention and cache reductions',`<p>Gemma uses four local layers per global layer in E2B and five per global elsewhere. Local layers use full RoPE with base 10K. Global layers use rotary fraction ${inlineMath(String.raw`p=0.25`)} with base 1M. Periodic full-context access restores communication that a local window cannot supply alone.</p><p>Global layers in 12B, 26B-A4B and 31B use keys as values. The unrotated key can supply values; the rotary fraction still needs position-dependent key storage. Under the stated representation, conventional ${inlineMath(String.raw`2d`)} storage becomes ${inlineMath(String.raw`d+pd`)}.</p>${eq(String.raw`\frac{2d-(d+pd)}{2d}=\frac{1-p}{2}=0.375\quad(p=1/4)`, `${inlineMath(String.raw`d>0`)} is head width and ${inlineMath(String.raw`p\in[0,1]`)} the rotary fraction. Under this cache representation, ${inlineMath(String.raw`K=V`)} retains d unrotated entries and pd positional key entries instead of separate ${inlineMath(String.raw`2d`)} K/V entries. The 37.5% is this global-cache component’s reduction, not total runtime memory.`)}<p>For an illustrative head width of 128 and rotary fraction one quarter, count scalar entries per token. This is a storage calculation, not a measured runtime allocation.</p>${table('Illustrative global-cache payload per head and token',['Representation','Scalar entries','What is retained'],[['Separate key and value','256','128 key + 128 value'],['Shared unrotated key/value','128','One shared unrotated representation'],['Additional rotated key slice','32','Position-dependent quarter of the key']])}<p>The shared representation and rotated slice total 160 entries. The baseline has 256, so 96 entries are removed. Multiply both payloads by the same element size to compare bytes. Local-layer caches, other layers, quantization metadata and workspaces remain outside this calculation.</p><p>E2B/E4B instead report explicit cache sharing ratios ${inlineMath(String.raw`\frac{20}{35}`)} and ${inlineMath(String.raw`\frac{18}{42}`)}. Do not apply the larger models' ${inlineMath(String.raw`K=V`)} formula to them. Layer sharing, locality and numerical precision affect different cache terms. <a href="${link('models/attention')}">Attention →</a> explains the operators separately.</p>`)}
${section('modalities','Put modality work in encoders or the decoder',`<p>Gemma's frozen 150M/550M vision encoders use 16-pixel patches, variable aspect ratios, axial 2D RoPE and learned absolute coordinates. Image budgets range through 70, 140, 280, 560 and 1,120 tokens. Preserve aspect ratio, round to pooled-patch multiples and choose a representation under the token budget.</p><p>The edge audio encoder follows the Universal Speech Model (USM) design and has two downsampling convolutions and twelve Conformer layers. It emits continuous features every 40ms from Mel inputs; no vector quantization is used. Vision and audio encoder weights stay frozen during pretraining. Its 305M size is 55% below the older 680M encoder.</p><p>Encoder-free 12B projects 48×48×3 RGB patches through a 35M matrix, adds coordinate-derived embeddings and LayerNorm, then passes them into the decoder. Audio uses raw 16KHz samples in 640-sample/40ms chunks. Representation learning moves into the shared decoder; eliminating an encoder does not eliminate that work.</p><p>Competitive audio results establish viability for this model. They do not prove superiority under equal model size or compute. Frozen encoders can supply strong representations cheaply; encoder-free inputs can simplify runtime and fragmentation. Measure end-to-end cost and quality at the same modality budget.</p>`)}
${section('deployment','Train the arithmetic and interface you will serve',`${table('Gemma Table 3 values at 32K text context; original caption says “Gb”',['Model','Raw weights','Quantized weights','INT8 cache','Format'],gemmaMemory)}<p>The caption's “Gb” conflicts with the usual byte interpretation of parameter footprints. These are source values, not silently normalized units. The MoE active weights are 7.6 raw/2.8 quantized, while total is 52/16.2. Active weights must not substitute for resident inventory. E-model effective footprints also do not prove all stored parameters fit in that memory.</p><p>Mobile checkpoints use mixed per-channel INT2/INT4 weights and INT8 activations; open-runtime checkpoints use blockwise Q4_0. Per-block scalar bounds separately support FP16 activations. Precision, packing and runtime kernels form one export contract.</p><p>Vision W8A8 reports 400→200MB forward memory including compilation overhead. Its 44% latency comparison also changes the older model/hardware. Audio uses layer-cluster weight precisions of 2, 4 and 8 bits with 8-bit activations. Audio disk size 390→87MB compares a redesigned smaller encoder with mixed precision; it is not an isolated quantization ablation.</p><p>Gemma's four-layer autoregressive drafter—three local layers and one global layer—uses a separate embedder, previous main activation, token embeddings and cross-attention to main KV. It avoids separate draft prefill and supports variable draft length. For edge models, clustered output reduces the final d×262K projection to d×4,096. Similar reported acceptance does not establish unchanged end-to-end quality without the verifier. <a href="${link('execution/speculation')}">Speculative Decoding →</a></p><p>Pretrained termination uses &lt;eos&gt;; instruction turns use &lt;turn|&gt;. A leading-system &lt;|think|&gt; selects reasoning, with the reasoning wrapper &lt;|channel&gt;thought …&lt;channel|&gt;. Tool declarations and calls have separate control tokens. Preserve the checkpoint's template and stop contract during fine-tuning. A successful tensor load does not prove a compatible conversation interface.</p>`)}
${section('gemma-training','Training infrastructure is part of the recipe',`<p>Gemma pretraining includes web, code, images and audio for E2B/E4B/12B, with a January 2025 cutoff. Benchmark contamination, unsafe material and recitation risk are filtered. Token counts, mixture weights, optimizers and detailed curricula are not disclosed.</p><p>Training uses TPUv5p/v6e, 4,096–12,288 chips, with data/sequence/replica partitioning, ZeRO-3 optimizer-state sharding, Pathways reductions and JAX/GSPMD/XLA. Slice-Granularity Elasticity continues with fewer slices after localized failure. Reported interruption falls from minutes to seconds; temporary lower capacity can improve goodput, not peak FLOPs.</p><p>Post-training adds thinking behavior and filters personal information, toxicity, mistaken model identity and duplicates. Attribution, calibrated hedging and refusals teach how to respond when evidence is weak. Reported factuality gains do not disclose enough data or reward detail to reproduce the pipeline fully.</p><p>E2B approaches older 27B text results on selected tasks; E4B approaches its vision results with a small InfographicVQA deficit. For 31B at 128K, RULER is 96.4 versus 66.0 and LOFT recall 79.5 versus 8.6. E4B also improves reported average speech translation and transcription over Gemma 3n with the smaller quantized audio encoder. Most static Gemma 4 results use thinking mode while Gemma 3 often does not. Vision results at 1,120 versus 280 tokens are not interchangeable. A dated Arena rank is product evidence, not a stable architecture property.</p>`)}
${section('apple','Apple: choose a flash-backed subnetwork',`<p>Apple Foundation Models (AFM) became a five-model stack in the June 8, 2026 overview. The tiers separate local latency and memory constraints from cloud reasoning and image generation. Private Cloud Compute (PCC) is Apple's server-side deployment environment, not a sixth model.</p>${table('Apple June 2026 model tiers; stored and active counts are different',['Tier','Deployment','Role'],[['AFM 3 Core','On-device; about 3B dense','General local model'],['AFM 3 Core Advanced','On-device; 20B stored, 1–4B active','Multimodal, dictation, expressive speech'],['AFM 3 Cloud','PCC; Apple silicon','General cloud model, multimodal reasoning'],['ADM 3 Cloud (Image)','PCC; Apple silicon','Image generation and editing'],['AFM 3 Cloud Pro','PCC; NVIDIA GPUs in Google Cloud','Difficult reasoning and agentic tool use']])}<p>Core Advanced addresses flash-to-DRAM bandwidth. A standard resident MoE can route every token cheaply relative to its memory bandwidth. The same policy may become too expensive if every new expert choice requires loading weights from NAND flash. Low active parameter count alone does not solve that transfer cost.</p><ol class="compact-ifp-steps"><li><strong>Store the inventory.</strong> Keep the full sparse model in NAND; retain always-active shared weights.</li><li><strong>Select for the request.</strong> A lightweight dense block chooses a fixed subset of routed experts during initial processing.</li><li><strong>Load a working subnetwork.</strong> Move selected experts into DRAM and combine them with shared weights.</li><li><strong>Generate and reselect.</strong> Run that subnetwork for a period, then periodically replace the active expert set.</li></ol><p>Apple calls this Instruction-Following Pruning (IFP). The request receives a predetermined active-parameter budget based on its use case. This is inference-time elasticity, not token-by-token top-k routing with all experts already resident. The overview does not disclose a complete expert layout or reselection interval. <a href="${link('models/moe#request-routing')}">MoE routing →</a> separates these choices. ${cite(refs.apple,'Apple overview')}</p>`)}
${section('apple-training','Specialize a common foundation for each tier',`<p>The overview reports scaled pretraining on cloud TPUs, followed by architecture/use-case specialization. The common initial foundation branches toward audio, image understanding, long-context reasoning and image generation. Supervised fine-tuning and multi-stage RL follow; quantization-aware training targets the deployment hardware.</p><p>AFM 3 Cloud builds on the 2025 Parallel-Track Mixture-of-Experts (PT-MoE) foundation. Apple attributes greater training stability, reasoning and context recall to architectural refinements. Those broad claims do not disclose the 2026 layer layout. On-device IFP and cloud PT-MoE are different designs.</p><p>Token counts, optimizers, training context lengths, full sparse layouts and scaling regimes remain undisclosed in this overview. The June announcement's promised summer report is a historical statement, not evidence about the current existence of every later report. ${cite('https://machinelearning.apple.com/research/apple-foundation-models-tech-report-2025','2025 report for historical context')}</p><p>The overview's September 9 update adds an opt-in exception for improvement data. Do not repeat an unconditional claim that user interactions are never used. This describes the stated data policy; it is not an independent privacy audit.</p>`)}
${section('apple-api','Route the application, not just its tokens',`<p>The Foundation Models framework exposes on-device and PCC models through one Swift API. The June developer session reports image input on-device and common structured-output/tool interfaces. The model selector changes where computation occurs; it does not guarantee identical quality or behavior.</p>${table('WWDC26 session319; developer-facing limits, not inferred training contexts',['Property','On-device','PCC'],[['Connectivity','Offline operation','Internet required'],['Request allowance','No request limits','Daily per-user limits'],['Context','4K','32K'],['Reasoning','Local task capabilities','Explicit reasoning support']])}<p>Use local inference when offline availability, latency and local processing fit the task. Escalate to PCC when the task needs more context or reasoning. Evaluate the actual feature and handle server unavailability or usage limits. A unified API makes switching easier; it does not remove those deployment differences. ${cite('https://developer.apple.com/videos/play/wwdc2026/319/','WWDC26 session319')}</p>`)}
${section('apple-evidence','Read Apple’s product comparisons in scope',`<p>The 2026 overview emphasizes in-house human preference, feature-specific quality and comparisons with the 2025 generation. These are useful product signals, not a complete standardized cross-model benchmark suite.</p>${table('Apple overview comparisons; directions reported, not compute-matched ablations',['Comparison','Reported direction','Scope'],[['AFM 3 Core vs 2025 on-device','Better general-text preference','Human judgments'],['AFM 3 Cloud vs 2025 server','Better text preference','Human judgments'],['Cloud Pro vs Cloud','Better text and image understanding','Response satisfaction'],['Core Advanced vs production speech systems','Better expressive TTS and dictation','Feature-specific evaluation']])}<p>Core Advanced's sparse local execution, integrated audio/multimodality and the explicit cloud/image/reasoning tiers distinguish this stack from the simpler earlier local/server split. The evaluation does not isolate flash-backed routing as the cause of every quality gain. Nor does a tier's deployment target establish its complete training recipe.</p>`)}
${section('evidence','Compare scores with their complete budgets',`${table('Nanbeige 4 Thinking selected results; temperature .6, top-p .95, max 64K',['Benchmark','Nanbeige 4','Qwen3-32B','Qwen3-30B-A3B'],[['AIME 2024',90.4,81.4,89.2],['AIME 2025',85.6,72.9,85],['GPQA-Diamond',82.2,68.7,73.4],['SuperGPQA',53.2,54.1,56.8],['BFCL V4',53.8,47.9,48.6],['Fullstack Bench',48,58.2,54.4],['ArenaHard V2',60,48.4,60],['Multi-Challenge',41.2,39.2,49.4]])}<p>Nanbeige 4.2 evaluates at 256K context. Code-agent runs allow 250 turns, outputs up to 32K and four-to-ten-hour timeouts; most code-agent results average eight runs. Its reported SWE Verified 63.6, SWE Pro 46.9 and Terminal Bench 44.1 belong to that model–scaffold–tools–budget combination.</p>${table('Nanbeige 4.2 reported comparisons; evaluation budgets matter',['Benchmark','Nanbeige4.2-3B','Qwen3.5-9B','Gemma4-12B'],[["GDPval Rubrics",74.3,61.9,68.5],["PinchBench-V2",74.7,68.2,53.8],["MCP-Atlas",57.8,47.4,30.5],["SWE-Bench Verified",63.6,53.1,44.2],["SWE-Bench Pro",46.9,33.8,21.9],["Terminal-Bench 2.0",44.1,29.2,21.1],["GPQA-Diamond",87.4,81.7,78.8],["LiveCodeBench-V6",72.5,65.6,72],["SciCode",35.6,32.7,38.2],["IF-Bench",54.6,54.1,73.5],["Recruit-Bench",63.3,59,69.4]])}<p>Nanbeige leads these reported general-agent and code-agent comparisons. It does not win every reasoning and alignment task: Gemma leads SciCode, IF-Bench and Recruit-Bench. Current weights, retry policy, context compression and model-judge reliability all affect agent scores. Match those conditions before attributing a gain to looping or parameter size.</p><p>For Nanbeige 4, quality-labeling models, retrieval infrastructure and many optimization details remain unavailable; some teachers and evaluators are proprietary. Final comparisons do not isolate component effects. Raw/filtered datasets, teachers, reward systems, task generators and much training compute remain unavailable. Some tests use in-house harnesses or benchmarks; several agent tests use model judges. Matched settings support within-harness comparisons, not scaffold-independent intrinsic model rankings. Preserve uncertainty at the component level even when final quality is strong.</p>`)}
${section('transfer','Turn a recipe into a controlled experiment',`<p>First name the bottleneck: vocabulary storage, per-token depth, long-context cache, malformed actions, sparse verification or expert-transfer traffic. Change one relevant mechanism under a matched budget and retain its supporting conditions.</p><p>For looping, verify pass-indexed caches and compare matched data/compute—not only stored weights. For masking, inspect target spans and denominator while retaining causal observations. For length control, test missing history, zero success and denominator limits. For deployment, validate the exact dtype, quantization packing, template, hardware and modality workload.</p><p><a href="${link('training/data')}">Training Data →</a>, <a href="${link('training/scaling')}">Scaling Laws →</a> and <a href="${link('training/numerics')}">Precision →</a> own the reusable mechanisms. <a href="${link('training/optimization#schedules')}">WSD scheduling →</a>, <a href="${link('post-training/sft')}">SFT →</a> and <a href="${link('post-training/rl')}">RL →</a> connect the reusable training choices. The complete recipes here explain why those choices appear together without treating one final benchmark as an ablation.</p>`)}
${section('sources','Sources and connected recipes',`<p>${Object.entries(refs).map(([k,v])=>cite(v,k)).join(' · ')}</p><p>${cite('https://huggingface.co/Nanbeige','Nanbeige checkpoints')} · <a href="${link('models/position')}">Positional Encodings →</a> · <a href="${link('execution/serving')}">Serving Models →</a> · <a href="${link('training/practice')}">Run Design and Goodput →</a></p><p>Parameter, cache and reward demonstrations are analytical examples. Measured behavior and schedule tables retain the report conditions. Missing protocols are not filled with guessed defaults.</p>`)}
`);}
export function mountCompact(scope=document){mountTopic(scope,compactMeta.slug,article=>{for(const name of ['embedding','loop','length']){const lab=article.querySelector(`[data-compact-lab="${name}"]`),selects=[...lab.querySelectorAll('select')],inputs=[...lab.querySelectorAll('input')],draw=()=>{lab.querySelector('[data-body]').innerHTML=name==='embedding'?embeddingBody(Number(selects[0].value),selects[1].value==='tied'):name==='loop'?loopBody(Number(selects[0].value),selects[1].value==='shared',Number(inputs[0].value)):lengthBody(Number(inputs[0].value),Number(inputs[1].value)/10,selects[0].value==='constrained');};if(name==='loop'){const p=rangePlayback(article,lab,draw,22000);for(const s of selects)s.addEventListener('change',()=>{p.stop();draw();});}else for(const c of [...selects,...inputs])c.addEventListener(c.tagName==='SELECT'?'change':'input',draw);draw();}});}
compactMeta.searchText=compactReader(()=> '').replace(/<[^>]*>/g,' ');
